        'en' => ['title' => 'Deregistering after a death', 'lead' => 'After a relative dies, their contribution account keeps running until it is deregistered. We carefully prepare the deregistration and submit it for you, without trips to any office.',
            'yes' => ['A relative has died and had their own contribution account.', 'You are entitled to act for the deceased person or the estate.', 'The home is being given up, or someone continues to live there.'],
            'no' => [['The home was paid for by another person who is still alive.', null]],
            'needed' => ['Name, contribution number and address of the deceased', 'Date of death and a copy of the death certificate', 'Your contact details and proof that you are entitled to apply'],
